import { type ZoneKey } from "./zones";

export type KingdomRunaroundImage = {
  dataUrl: string;
  uploadedAt: string;
  filename?: string;
};

export type PromptToken =
  | { kind: "word"; wordIndex: number }
  | { kind: "separator"; text: string };

export type PromptWord = {
  wordIndex: number;
  length: number;
  revealedText?: string;
};

export const KINGDOM_RUNAROUND_REACTIONS = ["🫶", "👍", "😵‍💫"] as const;
export const KINGDOM_RUNAROUND_REACTION_COOLDOWN_SECONDS = 30;

export type KingdomRunaroundReaction =
  (typeof KINGDOM_RUNAROUND_REACTIONS)[number];

export type PublicKingdomRunaroundAssignment = {
  index: number;
  zone_1?: ZoneKey;
  zone_2?: ZoneKey;
  tokens: PromptToken[];
  words: PromptWord[];
  images: KingdomRunaroundImage[];
  latestReaction?: KingdomRunaroundReaction;
  latestReactionAt?: string;
};

export type RevealedWord = {
  wordIndex: number;
  text: string;
};

export type WordRevealUpdate = {
  id?: number;
  assignmentIndex: number;
  revealedWords: RevealedWord[];
};

export type KingdomRunaroundAssignmentsUpdate = {
  id: number;
  assignments: PublicKingdomRunaroundAssignment[];
};

export type KingdomRunaroundRealtimeUpdate =
  | ({ type: "word_reveal" } & WordRevealUpdate)
  | ({ type: "assignments" } & KingdomRunaroundAssignmentsUpdate);
