// Server-rendered entrypoint for the Kingdom Runaround puzzle page. Runs in the SSR
// environment and mounts the client bundle via puzzle.client.tsx.
import { type PuzzleContentProps } from "@hunt/domain";
import { HorizontalDivider, PuzzleInfoBox } from "@hunt/puzzle-components";
import React from "react";
import { KingdomRunaroundArchivalMode } from "./ArchivalMode";
import { KingdomRunaroundAssignmentsProvider } from "./KingdomRunaroundAssignmentsContext";
import { PromptChecker } from "./PromptChecker";
import { type PublicKingdomRunaroundAssignment } from "./publicTypes";
import { useKingdomRunaroundAssignments } from "./useAssignments";

const InstructionBox = () => (
  <PuzzleInfoBox copyable={true}>
    <p>
      Please send an email to mitmh2026+kingdomrunaround@mit.edu when your team
      is ready with the title &quot;Joining the Night Swatch&quot;. You will
      need to send 1+ puzzlers (5-7 recommended, 9 maximum) with a laptop to the
      Student Center for this activity. We will reply with an assigned time and
      location. Please keep an eye out for replies.
    </p>
  </PuzzleInfoBox>
);

const LivePuzzleInner = () => {
  const { assignments, loading, error, applyWordReveal } =
    useKingdomRunaroundAssignments();

  const assignmentsWithImages = assignments.filter(
    (assignment) => assignment.images.length > 0,
  );

  let body: React.ReactNode;
  if (loading) {
    body = (
      <div className="space-y-4">
        <p>Loading communications from the Night Swatch...</p>
      </div>
    );
  } else if (error) {
    body = (
      <div className="space-y-4">
        <p>
          We couldn&apos;t retrieve communications from the Night Swatch right
          now. Please refresh the page in a moment.
        </p>
      </div>
    );
  } else if (assignmentsWithImages.length === 0) {
    body = <></>;
  } else {
    body = (
      <>
        <div className="rounded-lg border border-slate-200 bg-white/60 p-4 text-sm text-slate-700 shadow-sm">
          <p>
            To convince the Keeper to join your quest, your team must prove it
            can create beautiful murals that convey unity. Do so by guessing the
            ideas your team&apos;s Night Swatchers are trying to express.
          </p>
        </div>
        <div className="grid gap-6">
          {assignmentsWithImages.map((assignment) => (
            <PromptChecker
              key={assignment.index}
              assignment={assignment}
              onReveal={applyWordReveal}
            />
          ))}
        </div>
      </>
    );
  }

  return (
    <div className="flex flex-col gap-6">
      <InstructionBox />
      {body}
    </div>
  );
};

export const KingdomRunaroundPuzzleApp = ({
  assignments,
  archivalMode = false,
  archiveDomain,
}: {
  assignments?: PublicKingdomRunaroundAssignment[];
  archivalMode?: boolean;
  archiveDomain?: string;
}): React.JSX.Element => {
  return (
    <KingdomRunaroundAssignmentsProvider assignments={assignments}>
      {archivalMode ? (
        <div className="flex flex-col gap-6">
          <KingdomRunaroundArchivalMode archiveDomain={archiveDomain} />
        </div>
      ) : (
        <LivePuzzleInner />
      )}
    </KingdomRunaroundAssignmentsProvider>
  );
};

const PostHuntPuzzle = ({
  kingdomRunaroundAssignments,
}: {
  kingdomRunaroundAssignments?: PublicKingdomRunaroundAssignment[];
}) => {
  return (
    <>
      <div>
        <p>
          Teams were asked to send up to 9 people to the West(eros) Lounge on
          the 2nd floor of the Student Center with at least one laptop to join
          the Night Swatch.
        </p>
        <p>There, the Night Swatchers were told this:</p>
        <blockquote className="border-l-4 border-slate-600 pl-4 my-2 ml-4 text-slate-600">
          <p>Welcome Puzzlers. Thank you for joining the Night Swatch.</p>
          <p>
            To convince the Keeper of Mysteries to join you on your quest, you
            must prove that you are capable of creating beautiful murals that
            convey a message of unity throughout the Kingdom of the Puzzmon.
          </p>
          <p>
            To do this, you will be given nine prompts. For each prompt, you
            must create a mural using the colorful square swatches on grid
            paper. The rules are:
          </p>
          <ul className="list-disc pl-5">
            <li>Work only within one paper per prompt.</li>
            <li>The color swatches should be placed in the grid, </li>
            <li>
              Do not fold, write on, or otherwise destroy the swatches and
              paper.
            </li>
            <li>Do not swatch words (symbols and onomatopoeia are fine). </li>
          </ul>
          <p>
            When you are done with swatching a mural, please call a member of
            the research staff and they will transmit your artwork to your team,
            who will need to figure out the messages depicted in your murals.
            You can transmit up to 5 images per prompt.{" "}
          </p>
        </blockquote>
        <p>
          You can replicate the guessing experience by using the archival mode
          below to guess prompts with the art created by teams during the live
          Hunt. The swatching experience can be replicated by following the
          instructions in{" "}
          <a
            href="https://docs.google.com/spreadsheets/d/1AwMZj1plzq9dCwdM6BQp6tawWNDXmK9ZSmX-2TbtPKI/edit?usp=sharing"
            target="_blank"
            rel="noopener noreferrer"
          >
            this sheet
          </a>
          .
        </p>
      </div>
      <HorizontalDivider />
      <div id="kingdom-runaround-root">
        <KingdomRunaroundPuzzleApp
          assignments={kingdomRunaroundAssignments}
          archivalMode={true}
        />
      </div>
    </>
  );
};

const Puzzle = ({
  kingdomRunaroundAssignments,
  teamState,
}: PuzzleContentProps): React.JSX.Element => {
  const isArchival = teamState.gates_satisfied.includes("archival_mode");

  if (isArchival) {
    return (
      <PostHuntPuzzle
        kingdomRunaroundAssignments={kingdomRunaroundAssignments}
      />
    );
  }

  return (
    <div id="kingdom-runaround-root">
      <KingdomRunaroundPuzzleApp assignments={kingdomRunaroundAssignments} />
    </div>
  );
};

export default Puzzle;
