import { Md5 } from "ts-md5";
import { canonicalizeWord } from "./canonicalization";

export type PromptTokenInternal =
  | { kind: "word"; wordIndex: number }
  | { kind: "separator"; text: string };

export type PromptWordInfo = {
  wordIndex: number;
  text: string;
  canonical: string;
  length: number;
  hash: string;
};

export type PromptMetadata = {
  tokens: PromptTokenInternal[];
  words: PromptWordInfo[];
};

export const hashCanonicalWord = (canonical: string): string =>
  Md5.hashStr(canonical);

export const buildPromptMetadata = (prompt: string): PromptMetadata => {
  const tokens: PromptTokenInternal[] = [];
  const words: PromptWordInfo[] = [];
  const wordRegex = /([A-Za-z]+(?:'[A-Za-z]+)*)/g;
  let wordIndex = 0;
  let lastIndex = 0;
  let match: RegExpExecArray | null;

  while ((match = wordRegex.exec(prompt)) !== null) {
    const [word] = match;
    if (match.index > lastIndex) {
      tokens.push({
        kind: "separator",
        text: prompt.slice(lastIndex, match.index),
      });
    }

    const canonical = canonicalizeWord(word);
    const hash = hashCanonicalWord(canonical);

    tokens.push({ kind: "word", wordIndex });
    words.push({
      wordIndex,
      text: word,
      canonical,
      length: word.length,
      hash,
    });
    wordIndex += 1;
    lastIndex = wordRegex.lastIndex;
  }

  if (lastIndex < prompt.length) {
    tokens.push({
      kind: "separator",
      text: prompt.slice(lastIndex),
    });
  }

  return { tokens, words };
};
