// Client entrypoint that hydrates the SSR markup for the Kingdom Runaround puzzle. This
// file is only executed in the browser.
import React from "react";
import { hydrateRoot } from "react-dom/client";
import { type PublicKingdomRunaroundAssignment } from "./publicTypes";
import { KingdomRunaroundPuzzleApp } from "./puzzle";

const elem = document.getElementById("kingdom-runaround-root");

if (elem) {
  const windowState = window as unknown as {
    initialKingdomRunaroundAssignments?: PublicKingdomRunaroundAssignment[];
    initialKingdomRunaroundArchivalMode?: boolean;
  };
  const assignments = windowState.initialKingdomRunaroundAssignments;
  const archivalMode = windowState.initialKingdomRunaroundArchivalMode === true;

  hydrateRoot(
    elem,
    <KingdomRunaroundPuzzleApp
      assignments={assignments ?? undefined}
      archivalMode={archivalMode}
    />,
  );
}
