// Client-side hook that manages assignment data and real-time updates in the
// browser. It should never run during SSR.
import { useCallback, useEffect, useRef, useState } from "react";
import { useKingdomRunaroundAssignmentsContext } from "./KingdomRunaroundAssignmentsContext";
import {
  type PublicKingdomRunaroundAssignment,
  type KingdomRunaroundRealtimeUpdate,
  type WordRevealUpdate,
  type KingdomRunaroundReaction,
} from "./publicTypes";
import { subscribeToKingdomRunaroundUpdates } from "./socket";

type FetchState =
  | { status: "idle"; assignments: PublicKingdomRunaroundAssignment[] }
  | { status: "loading"; assignments: PublicKingdomRunaroundAssignment[] }
  | { status: "success"; assignments: PublicKingdomRunaroundAssignment[] }
  | { status: "error"; assignments: PublicKingdomRunaroundAssignment[] };

export const useKingdomRunaroundAssignments = (): {
  assignments: PublicKingdomRunaroundAssignment[];
  loading: boolean;
  error: boolean;
  applyWordReveal: (update: WordRevealUpdate) => void;
} => {
  const contextAssignments = useKingdomRunaroundAssignmentsContext() as
    | PublicKingdomRunaroundAssignment[]
    | undefined;
  // When SSR gives us assignments via context we can skip the initial fetch and
  // move straight into the success state; otherwise we start "idle" and kick
  // off the HTTP request below.
  const [state, setState] = useState<FetchState>(() => {
    if (contextAssignments) {
      return { status: "success", assignments: contextAssignments };
    }
    return { status: "idle", assignments: [] };
  });
  const [realtimeReady, setRealtimeReady] = useState(
    () => contextAssignments !== undefined,
  );
  const kingdomRunaroundSubRef = useRef<(() => void) | null>(null);
  const pendingWordRevealsRef = useRef<WordRevealUpdate[]>([]);

  const applyQueuedWordReveals = useCallback(
    (assignments: PublicKingdomRunaroundAssignment[]) => {
      if (pendingWordRevealsRef.current.length === 0) {
        return assignments;
      }
      const updates = pendingWordRevealsRef.current;
      pendingWordRevealsRef.current = [];
      return updates.reduce(
        (acc, updateEntry) => mergeWordReveal(acc, updateEntry),
        assignments,
      );
    },
    [],
  );

  const applyWordReveal = useCallback((update: WordRevealUpdate) => {
    setState((prev) => {
      if (prev.status === "idle") {
        pendingWordRevealsRef.current.push(update);
        return prev;
      }
      return {
        ...prev,
        assignments: mergeWordReveal(prev.assignments, update),
      };
    });
  }, []);

  useEffect(() => {
    if (contextAssignments) {
      setState({
        status: "success",
        assignments: applyQueuedWordReveals(contextAssignments),
      });
      setRealtimeReady(true);
      return;
    }

    let cancelled = false;
    setState((prev) => ({
      status: "loading",
      assignments: prev.assignments,
    }));
    // Fetch the Kingdom Runaround assignments client-side if SSR did not
    // provide them (or the initial payload failed), mirroring the data the
    // server normally injects via
    // PuzzleContentProps/window.initialKingdomRunaroundAssignments.
    void (async () => {
      try {
        const response = await fetch("/api/public/kingdom-runaround/uploads", {
          credentials: "include",
        });
        if (!response.ok) {
          if (!cancelled) {
            setState({ status: "error", assignments: [] });
          }
          return;
        }
        const jsonResult: unknown = await response.json();
        const payload = jsonResult as {
          assignments?: PublicKingdomRunaroundAssignment[];
        };
        if (cancelled) {
          return;
        }
        const assignments = Array.isArray(payload.assignments)
          ? payload.assignments
          : ([] as PublicKingdomRunaroundAssignment[]);
        setState((prev) => {
          const merged = mergeAssignments(prev.assignments, assignments);
          return {
            status: "success",
            assignments: applyQueuedWordReveals(merged),
          };
        });
        setRealtimeReady(true);
      } catch (error: unknown) {
        console.warn("Failed to load Kingdom Runaround assignments", error);
        if (!cancelled) {
          setState({ status: "error", assignments: [] });
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [contextAssignments, applyQueuedWordReveals]);

  useEffect(() => {
    if (!realtimeReady || typeof window === "undefined") {
      return;
    }
    if (kingdomRunaroundSubRef.current) {
      return;
    }
    kingdomRunaroundSubRef.current = subscribeToKingdomRunaroundUpdates(
      (update: KingdomRunaroundRealtimeUpdate) => {
        if (update.type === "word_reveal") {
          applyWordReveal(update);
          return;
        }
        if (update.type === "assignments") {
          setState((prev) => {
            const merged = mergeAssignments(
              prev.assignments,
              update.assignments,
            );
            return {
              status: "success",
              assignments: applyQueuedWordReveals(merged),
            };
          });
        }
      },
    );
    return () => {
      kingdomRunaroundSubRef.current?.();
      kingdomRunaroundSubRef.current = null;
    };
  }, [realtimeReady, applyWordReveal, applyQueuedWordReveals]);

  return {
    assignments: state.assignments,
    loading: state.status === "loading" && state.assignments.length === 0,
    error: state.status === "error",
    applyWordReveal,
  };
};

const mergeWordReveal = (
  assignments: PublicKingdomRunaroundAssignment[],
  update: WordRevealUpdate,
): PublicKingdomRunaroundAssignment[] => {
  return assignments.map((assignment) => {
    if (assignment.index !== update.assignmentIndex) {
      return assignment;
    }
    const updatedWords = assignment.words.map((word) => {
      if (word.revealedText) {
        return word;
      }
      const revealed = update.revealedWords.find(
        (entry) => entry.wordIndex === word.wordIndex,
      );
      if (!revealed) {
        return word;
      }
      return { ...word, revealedText: revealed.text };
    });
    return {
      ...assignment,
      words: updatedWords,
    };
  });
};

const mergeAssignmentWords = (
  incomingAssignment: PublicKingdomRunaroundAssignment,
  previousAssignment: PublicKingdomRunaroundAssignment | undefined,
) => {
  if (!previousAssignment) {
    return incomingAssignment.words;
  }
  const previousWords = new Map(
    previousAssignment.words.map((word) => [word.wordIndex, word.revealedText]),
  );
  return incomingAssignment.words.map((word) => {
    if (word.revealedText) {
      return word;
    }
    const previousReveal = previousWords.get(word.wordIndex);
    if (previousReveal === undefined) {
      return word;
    }
    return { ...word, revealedText: previousReveal };
  });
};

const pickLatestTimestamp = (
  incoming?: string,
  previous?: string,
): string | undefined => {
  const incomingDate = incoming ? new Date(incoming).getTime() : undefined;
  const previousDate = previous ? new Date(previous).getTime() : undefined;
  const validIncoming =
    incomingDate !== undefined && !Number.isNaN(incomingDate);
  const validPrevious =
    previousDate !== undefined && !Number.isNaN(previousDate);
  if (validIncoming && validPrevious) {
    return incomingDate >= previousDate ? incoming : previous;
  }
  if (validIncoming) {
    return incoming;
  }
  if (validPrevious) {
    return previous;
  }
  return undefined;
};

const pickLatestReaction = (
  incomingReaction?: KingdomRunaroundReaction,
  incomingAt?: string,
  previousReaction?: KingdomRunaroundReaction,
  previousAt?: string,
): KingdomRunaroundReaction | undefined => {
  const latestTimestamp = pickLatestTimestamp(incomingAt, previousAt);
  if (!latestTimestamp) {
    return incomingReaction ?? previousReaction ?? undefined;
  }
  if (latestTimestamp === incomingAt) {
    return incomingReaction ?? previousReaction ?? undefined;
  }
  return previousReaction ?? incomingReaction ?? undefined;
};

const mergeAssignments = (
  current: PublicKingdomRunaroundAssignment[],
  incoming: PublicKingdomRunaroundAssignment[],
): PublicKingdomRunaroundAssignment[] => {
  const currentByIndex = new Map(
    current.map((assignment) => [assignment.index, assignment]),
  );
  const incomingIndices = new Set(
    incoming.map((assignment) => assignment.index),
  );
  const mergedIncoming = incoming.map((assignment) => {
    const existing = currentByIndex.get(assignment.index);
    if (!existing) {
      return assignment;
    }
    return {
      ...assignment,
      words: mergeAssignmentWords(assignment, existing),
      latestReaction: pickLatestReaction(
        assignment.latestReaction,
        assignment.latestReactionAt,
        existing.latestReaction,
        existing.latestReactionAt,
      ),
      latestReactionAt: pickLatestTimestamp(
        assignment.latestReactionAt,
        existing.latestReactionAt,
      ),
    };
  });
  const untouched = current.filter(
    (assignment) => !incomingIndices.has(assignment.index),
  );
  const mergedAssignments = mergedIncoming.concat(untouched);
  mergedAssignments.sort((a, b) => a.index - b.index);
  return mergedAssignments;
};
