// Client-only socket helper for subscribing to Kingdom Runaround websocket updates. This
// module must never be imported in a server-only path.
import { SocketManager } from "@hunt/socket-manager";
import { type KingdomRunaroundRealtimeUpdate } from "./publicTypes";

type KingdomRunaroundDataset = "kingdom_runaround";

type SocketManagerInstance = {
  watch: (
    dataset: KingdomRunaroundDataset,
    params: undefined,
    initialValue: KingdomRunaroundRealtimeUpdate[],
    onUpdate: (value: KingdomRunaroundRealtimeUpdate) => void,
  ) => () => void;
};

type SocketManagerConstructor = new (args: {
  onConnectionStateChange: (state: unknown) => void;
  wsBaseUrl?: string;
}) => SocketManagerInstance;

const SocketManagerImpl = SocketManager as unknown as SocketManagerConstructor;

let singletonManager: SocketManagerInstance | null = null;

type BrowserWindow = Window & { wsBaseUrl?: string };

const ensureClientRuntime = () => {
  if (typeof window === "undefined") {
    throw new Error(
      "Kingdom Runaround SocketManager must only be instantiated in the browser.",
    );
  }
};

const getSocketManager = () => {
  ensureClientRuntime();
  if (!singletonManager) {
    const { wsBaseUrl } = window as BrowserWindow;
    singletonManager = new SocketManagerImpl({
      wsBaseUrl,
      onConnectionStateChange: () => {
        /* no-op for puzzle client */
      },
    });
  }
  return singletonManager;
};

export const subscribeToKingdomRunaroundUpdates = (
  onUpdate: (update: KingdomRunaroundRealtimeUpdate) => void,
): (() => void) => {
  if (typeof window === "undefined") {
    return () => {
      /* no-op on server */
    };
  }
  const manager = getSocketManager();
  return manager.watch("kingdom_runaround", undefined, [], onUpdate);
};
