// Client-only component that renders a guess form for one assignment. It uses
// browser APIs (fetch, React state) and must not run on the server.
import { twemojify } from "@hunt/shadcn";
import React, { useEffect, useMemo, useRef, useState } from "react";
import { canonicalizeWord } from "./canonicalization";
import { PROMPT_RECORDS } from "./data";
import { buildPromptMetadata } from "./promptMetadata";
import {
  KINGDOM_RUNAROUND_REACTIONS,
  KINGDOM_RUNAROUND_REACTION_COOLDOWN_SECONDS,
  type KingdomRunaroundReaction,
  type PublicKingdomRunaroundAssignment,
  type WordRevealUpdate,
} from "./publicTypes";

type PromptCheckerProps = {
  assignment: PublicKingdomRunaroundAssignment;
  rateLimitMs?: number;
  headingLevel?: keyof React.JSX.IntrinsicElements;
  onReveal: (update: WordRevealUpdate) => void;
};

const DEFAULT_RATE_LIMIT_MS = 1000;
const parseTimestamp = (value?: string | null): number | null => {
  if (!value) {
    return null;
  }
  const ms = Date.parse(value);
  return Number.isNaN(ms) ? null : ms;
};

const REACTION_LABELS: Record<KingdomRunaroundReaction, string> = {
  "🫶": "Send heart reaction",
  "👍": "Send thumbs up reaction",
  "😵‍💫": "Send dizzy reaction",
};

const buildCooldownTarget = (
  latestMs: number | null,
  explicitCooldownMs: number | null,
): number => {
  if (explicitCooldownMs !== null) {
    return explicitCooldownMs;
  }
  if (latestMs !== null) {
    return latestMs + KINGDOM_RUNAROUND_REACTION_COOLDOWN_SECONDS * 1000;
  }
  return Date.now() + KINGDOM_RUNAROUND_REACTION_COOLDOWN_SECONDS * 1000;
};

const getPromptForAssignment = (
  assignment: PublicKingdomRunaroundAssignment,
): string | null => {
  if (!assignment.zone_1 || !assignment.zone_2) {
    return null;
  }
  const record = PROMPT_RECORDS.find(
    (entry) =>
      (entry.zone_1 === assignment.zone_1 &&
        entry.zone_2 === assignment.zone_2) ||
      (entry.zone_1 === assignment.zone_2 &&
        entry.zone_2 === assignment.zone_1),
  );
  return record?.prompt ?? null;
};

export const PromptChecker = ({
  assignment,
  rateLimitMs = DEFAULT_RATE_LIMIT_MS,
  headingLevel = "h3",
  onReveal,
}: PromptCheckerProps) => {
  const [input, setInput] = useState("");
  const [lastCheckTimestamp, setLastCheckTimestamp] = useState(0);
  const [message, setMessage] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [reactionSubmitting, setReactionSubmitting] = useState(false);
  const [reactionMessage, setReactionMessage] = useState<string | null>(null);
  const [reactionCooldownUntil, setReactionCooldownUntil] = useState<
    number | null
  >(null);
  const [nowTs, setNowTs] = useState(() => Date.now());
  const [latestReactionAt, setLatestReactionAt] = useState<string | null>(
    assignment.latestReactionAt ?? null,
  );
  const [latestReaction, setLatestReaction] =
    useState<KingdomRunaroundReaction | null>(
      assignment.latestReaction ?? null,
    );
  const revealedWordCacheRef = useRef<Set<string>>(new Set());

  useEffect(() => {
    const cache = new Set<string>();
    assignment.words.forEach((word) => {
      if (word.revealedText) {
        cache.add(canonicalizeWord(word.revealedText));
      }
    });
    revealedWordCacheRef.current = cache;
  }, [assignment]);

  const HeadingTag = headingLevel;
  const promptMetadata = useMemo(() => {
    const prompt = getPromptForAssignment(assignment);
    return prompt ? buildPromptMetadata(prompt) : null;
  }, [assignment]);

  useEffect(() => {
    if (reactionCooldownUntil === null) {
      return;
    }
    const tick = () => {
      setNowTs(Date.now());
    };
    const interval = window.setInterval(tick, 500);
    const timeout = window.setTimeout(
      () => {
        setReactionCooldownUntil(null);
        tick();
      },
      Math.max(0, reactionCooldownUntil - Date.now()),
    );
    return () => {
      window.clearInterval(interval);
      window.clearTimeout(timeout);
    };
  }, [reactionCooldownUntil]);

  useEffect(() => {
    setLatestReaction(assignment.latestReaction ?? null);
    setLatestReactionAt(assignment.latestReactionAt ?? null);
    const latestMs = parseTimestamp(assignment.latestReactionAt);
    if (latestMs === null) {
      setReactionCooldownUntil(null);
      return;
    }
    const cooldownUntil =
      latestMs + KINGDOM_RUNAROUND_REACTION_COOLDOWN_SECONDS * 1000;
    setReactionCooldownUntil(cooldownUntil);
  }, [
    assignment.index,
    assignment.latestReaction,
    assignment.latestReactionAt,
  ]);

  const handleCheck = () => {
    const now = Date.now();
    if (now - lastCheckTimestamp < rateLimitMs) {
      const remaining = Math.ceil(
        (rateLimitMs - (now - lastCheckTimestamp)) / 100,
      );
      setMessage(
        `⏱️ Rate limited. Try again in ${(remaining / 10).toFixed(1)} seconds.`,
      );
      return;
    }

    setLastCheckTimestamp(now);

    const guess = input;
    const canonicalGuess = canonicalizeWord(guess);
    if (canonicalGuess.length === 0) {
      setMessage("Enter a word to check.");
      return;
    }
    if (revealedWordCacheRef.current.has(canonicalGuess)) {
      setMessage("That word was already confirmed.");
      return;
    }
    if (!promptMetadata) {
      setMessage("Unable to check this prompt offline.");
      return;
    }

    setSubmitting(true);
    setInput("");
    const matchingWords = promptMetadata.words.filter(
      (word) => word.canonical === canonicalGuess,
    );
    if (matchingWords.length === 0) {
      setMessage(`❌ "${guess}" does not match this prompt.`);
      setSubmitting(false);
      return;
    }

    const update: WordRevealUpdate = {
      assignmentIndex: assignment.index,
      revealedWords: matchingWords.map((word) => ({
        wordIndex: word.wordIndex,
        text: word.text,
      })),
    };
    revealedWordCacheRef.current.add(canonicalGuess);
    onReveal(update);
    setMessage(`✅ "${guess}" is now revealed for your whole team.`);
    setSubmitting(false);
  };

  const handleReaction = (reaction: KingdomRunaroundReaction) => {
    const coolingDown =
      reactionCooldownUntil !== null && reactionCooldownUntil > Date.now();
    if (reactionSubmitting || coolingDown) {
      return;
    }
    setReactionSubmitting(true);
    setReactionMessage(null);
    const now = Date.now();
    setLatestReaction(reaction);
    setLatestReactionAt(new Date(now).toISOString());
    setReactionCooldownUntil(buildCooldownTarget(now, null));
    setReactionMessage("Reaction sent.");
    setReactionSubmitting(false);
  };

  const isComplete =
    assignment.words.length > 0 &&
    assignment.words.every((word) => Boolean(word.revealedText));

  useEffect(() => {
    if (!isComplete) {
      return;
    }
    setMessage(null);
    setReactionMessage("Prompt solved");
    setReactionCooldownUntil(null);
  }, [isComplete]);

  const coolingDown =
    reactionCooldownUntil !== null && reactionCooldownUntil > nowTs;
  const reactionCooldownSeconds = coolingDown
    ? Math.max(0, Math.ceil((reactionCooldownUntil - nowTs) / 1000))
    : 0;
  const reactionDisabled =
    reactionSubmitting ||
    coolingDown ||
    isComplete ||
    assignment.words.length === 0;
  const latestReactionDateText = useMemo(() => {
    const latestReactionMs = parseTimestamp(latestReactionAt);
    if (latestReactionMs === null) {
      return null;
    }
    const date = new Date(latestReactionMs);
    return Number.isNaN(date.getTime()) ? null : date.toLocaleTimeString();
  }, [latestReactionAt]);

  return (
    <section
      className={`space-y-4 rounded-lg border p-4 shadow-sm ${
        isComplete
          ? "border-emerald-400 bg-emerald-50"
          : "border-slate-300 bg-slate-50"
      }`}
    >
      <HeadingTag className="text-lg font-semibold text-slate-800">
        Prompt {assignment.index + 1}
      </HeadingTag>
      <p className="leading-relaxed text-slate-700 font-mono tracking-widest">
        {assignment.tokens.map((token, idx) => {
          if (token.kind === "separator") {
            return <React.Fragment key={idx}>{token.text}</React.Fragment>;
          }
          const word = assignment.words[token.wordIndex];
          const revealed = word?.revealedText;
          const display = revealed ?? "_".repeat(word?.length ?? 1);
          return (
            <span
              key={idx}
              className={`inline-flex flex-col items-center ${
                revealed ? "bg-lime-200 font-semibold text-slate-900" : ""
              }`}
            >
              {display}
              {!revealed ? (
                <span className="text-xs font-normal tracking-normal text-slate-500">
                  ({word?.length ?? 0})
                </span>
              ) : null}
            </span>
          );
        })}
      </p>
      <div className="flex flex-wrap items-end gap-2">
        <label className="flex min-w-48 flex-1 flex-col gap-1">
          <span>Guess a word in the prompt:</span>
          <input
            type="text"
            value={input}
            onChange={(event) => {
              setInput(event.currentTarget.value);
            }}
            onKeyDown={(event) => {
              if (event.key === "Enter") {
                event.preventDefault();
                handleCheck();
              }
            }}
            className="w-full rounded border border-slate-300 px-3 py-2 text-base shadow-sm focus:border-indigo-500 focus:outline-none focus:ring"
            placeholder="Enter a word to guess"
          />
        </label>
        <button
          type="button"
          onClick={handleCheck}
          disabled={submitting || assignment.images.length === 0}
          className="flex h-10 items-center justify-center rounded bg-indigo-600 px-4 font-medium text-white shadow hover:bg-indigo-500 focus:outline-none focus:ring focus:ring-indigo-200 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {submitting ? "Checking..." : "Check"}
        </button>
      </div>
      {message ? <p className="text-sm text-slate-600">{message}</p> : null}

      <div className="space-y-2 rounded border border-slate-200 bg-white p-3">
        <p className="text-sm font-medium text-slate-700 pb-1">
          Send a reaction to your team&apos;s Night Swatchers (once every{" "}
          {KINGDOM_RUNAROUND_REACTION_COOLDOWN_SECONDS}s per prompt, timer
          shared across your team):
        </p>
        <div className="flex justify-between gap-4">
          <div className="flex flex-wrap gap-2">
            {KINGDOM_RUNAROUND_REACTIONS.map((reaction) => (
              <button
                key={reaction}
                type="button"
                aria-label={REACTION_LABELS[reaction]}
                className="flex h-12 w-12 items-center justify-center rounded border border-slate-300 bg-slate-50 text-xl shadow-sm hover:bg-slate-100 focus:outline-none focus:ring focus:ring-indigo-200 disabled:cursor-not-allowed disabled:opacity-50"
                onClick={() => {
                  handleReaction(reaction);
                }}
                disabled={reactionDisabled}
              >
                <span className="sr-only">{REACTION_LABELS[reaction]}</span>
                <span aria-hidden>{twemojify(reaction, "h-6 w-6")}</span>
              </button>
            ))}
          </div>
          <div className="inline-flex items-center gap-3 rounded border border-slate-200 bg-slate-50 px-3 py-2 text-sm font-semibold text-slate-700 leading-tight min-w-[220px]">
            <div className="flex flex-col leading-tight">
              <span className="text-slate-500">Latest reaction:</span>
              <span className="text-xs font-normal text-slate-500">
                {latestReactionDateText
                  ? `Sent ${latestReactionDateText}`
                  : "Sent —"}
              </span>
            </div>
            {latestReaction ? (
              <span aria-hidden className="inline-flex w-6 justify-center">
                {twemojify(latestReaction, "h-5 w-5 align-middle")}
              </span>
            ) : (
              <span className="text-slate-500 inline-flex w-6 justify-center">
                –
              </span>
            )}
          </div>
        </div>
        <div className="min-h-5">
          {reactionMessage ? (
            <p className="text-xs text-slate-600">{reactionMessage}</p>
          ) : coolingDown ? (
            <p className="text-xs text-slate-600">
              You can send a reaction in {reactionCooldownSeconds}s.
            </p>
          ) : null}
        </div>
      </div>
      {assignment.images.length > 0 ? (
        <div className="space-y-2 rounded border border-slate-200 bg-white p-3">
          <p className="text-sm font-medium text-slate-700">
            Uploaded references
          </p>
          <div className="grid gap-3 md:grid-cols-2">
            {assignment.images.map((image, idx) => (
              <figure
                key={`${image.uploadedAt}-${idx}`}
                className="space-y-1 rounded border border-slate-200 bg-slate-100 p-2"
              >
                <img
                  src={image.dataUrl}
                  alt={`From your teammates for Prompt ${assignment.index + 1}`}
                  className="max-h-64 w-full rounded object-contain bg-white"
                />
                <figcaption className="text-xs text-slate-600">
                  Uploaded{" "}
                  {new Date(image.uploadedAt).toLocaleString(undefined, {
                    hour: "numeric",
                    minute: "2-digit",
                    year: "numeric",
                    month: "short",
                    day: "numeric",
                  })}
                </figcaption>
              </figure>
            ))}
          </div>
        </div>
      ) : null}
    </section>
  );
};
