import { OVERWORLD_ROUND_SLUGS } from "@hunt/hunt-data";

export type ZoneSlug = (typeof OVERWORLD_ROUND_SLUGS)[number];
export type ZoneKey = ZoneSlug;

export const ZONES = OVERWORLD_ROUND_SLUGS as readonly ZoneKey[];

export const ZONE_DISPLAY_NAMES: Record<ZoneKey, string> = Object.fromEntries(
  ZONES.map((slug) => [
    slug,
    slug
      .split("_")
      .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
      .join(" "),
  ]),
) as Record<ZoneKey, string>;
