import { KINGDOM_RUNAROUND_SLUG } from "@hunt/hunt-data";
import { markLocalTaskSolved } from "@hunt/puzzle-components";
import React, { useCallback, useEffect, useMemo, useState } from "react";
import { canonicalizeWord } from "./canonicalization";
import { PROMPT_RECORDS } from "./data";
import { buildPromptMetadata } from "./promptMetadata";
import {
  type PublicKingdomRunaroundAssignment,
  type WordRevealUpdate,
} from "./publicTypes";
import { getAssignmentForSeed, makePairKey } from "./shared";
import { type ZoneKey, ZONE_DISPLAY_NAMES } from "./zones";

type ArchiveIndexFileEntry = {
  key?: string;
  metadata?: Record<string, unknown>;
};

type ArchiveIndexPayload = {
  filemap?: Record<string, ArchiveIndexFileEntry>;
};

type ArchiveImageEntry = {
  key: string;
  imageUrl: string;
  teamName: string;
};

type ArchivalPromptCheckerProps = {
  assignment: PublicKingdomRunaroundAssignment;
  shownImages: ArchiveImageEntry[];
  remainingImageCount: number;
  canAddImage: boolean;
  addImageDisabledReason?: string;
  onAddImage: () => void;
  onReveal: (update: WordRevealUpdate) => void;
};

const DEFAULT_SEED = "1";
const DEFAULT_RATE_LIMIT_MS = 1000;

const ARCHIVAL_REVEALED_STORAGE_KEY = "kingdom-runaround-archival-revealed";

type StoredRevealedWords = { wordIndex: number; text: string }[];

const getStoredRevealed = (): Record<string, StoredRevealedWords> => {
  if (typeof window === "undefined") {
    return {};
  }
  try {
    const raw = window.localStorage.getItem(ARCHIVAL_REVEALED_STORAGE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw) as Record<string, unknown>;
    const result: Record<string, StoredRevealedWords> = {};
    for (const [key, value] of Object.entries(parsed)) {
      if (Array.isArray(value)) {
        const words = value.filter(
          (entry): entry is { wordIndex: number; text: string } =>
            typeof entry === "object" &&
            entry !== null &&
            typeof (entry as { wordIndex?: unknown }).wordIndex === "number" &&
            typeof (entry as { text?: unknown }).text === "string",
        );
        if (words.length > 0) result[key] = words;
      }
    }
    return result;
  } catch {
    return {};
  }
};

const saveStoredRevealedForPair = (
  pairKey: string,
  words: StoredRevealedWords,
): void => {
  if (typeof window === "undefined") return;
  try {
    const stored = getStoredRevealed();
    const next =
      words.length > 0
        ? { ...stored, [pairKey]: words }
        : Object.fromEntries(
            Object.entries(stored).filter(([k]) => k !== pairKey),
          );
    window.localStorage.setItem(
      ARCHIVAL_REVEALED_STORAGE_KEY,
      JSON.stringify(next),
    );
  } catch {
    // ignore
  }
};

const mergeStoredRevealed = (
  assignments: PublicKingdomRunaroundAssignment[],
): PublicKingdomRunaroundAssignment[] => {
  const stored = getStoredRevealed();
  if (Object.keys(stored).length === 0) return assignments;
  return assignments.map((assignment) => {
    if (!assignment.zone_1 || !assignment.zone_2) return assignment;
    const pairKey = makePairKey(assignment.zone_1, assignment.zone_2);
    const storedWords = stored[pairKey];
    if (!storedWords?.length) return assignment;
    const byIndex = new Map(storedWords.map((w) => [w.wordIndex, w.text]));
    return {
      ...assignment,
      words: assignment.words.map((word) => {
        const text = byIndex.get(word.wordIndex);
        if (!text) return word;
        return { ...word, revealedText: text };
      }),
    };
  });
};

const ZONE_KEY_SET = new Set<string>(Object.keys(ZONE_DISPLAY_NAMES));

const asZoneKey = (value: string | undefined): ZoneKey | null => {
  if (!value || !ZONE_KEY_SET.has(value)) {
    return null;
  }
  return value as ZoneKey;
};

const normalizeArchiveDomain = (domain?: string): string | null => {
  if (!domain) {
    return null;
  }
  const trimmed = domain.trim();
  if (trimmed.length === 0) {
    return null;
  }
  return trimmed.replace(/^https?:\/\//i, "").replace(/\/+$/, "");
};

const getArchiveDomainFromWindow = (): string | undefined => {
  if (typeof window === "undefined") {
    return undefined;
  }
  return (
    (window as unknown as { initialMidhuntArchiveDomain?: string })
      .initialMidhuntArchiveDomain ?? undefined
  );
};

const decodeBase64Utf8 = (value: string): string | null => {
  try {
    const binary = atob(value);
    const bytes = Uint8Array.from(binary, (char) => char.charCodeAt(0));
    return new TextDecoder().decode(bytes);
  } catch {
    return null;
  }
};

const readTeamName = (metadata: Record<string, string>): string => {
  const explicitTeamName = metadata.team_name?.trim();
  if (explicitTeamName) {
    return explicitTeamName;
  }

  const encodedTeamName = metadata.team_name_b64_utf8?.trim();
  if (encodedTeamName) {
    const decoded = decodeBase64Utf8(encodedTeamName);
    if (decoded) {
      return decoded;
    }
  }

  const teamId = metadata.team_id?.trim();
  if (teamId) {
    return `Team ${teamId}`;
  }
  return "Unknown team";
};

const buildAssignmentSetFromSeed = (
  seed: string,
): PublicKingdomRunaroundAssignment[] => {
  return getAssignmentForSeed(seed).map((assignment) => {
    const metadata = buildPromptMetadata(assignment.prompt);
    return {
      index: assignment.index,
      zone_1: assignment.zone_1,
      zone_2: assignment.zone_2,
      tokens: metadata.tokens,
      words: metadata.words.map((word) => ({
        wordIndex: word.wordIndex,
        length: word.length,
      })),
      images: [],
    };
  });
};

const buildArchiveImageIndex = ({
  payload,
  archiveDomain,
}: {
  payload: ArchiveIndexPayload;
  archiveDomain: string;
}): Map<string, ArchiveImageEntry[]> => {
  const byPair = new Map<string, Map<string, ArchiveImageEntry>>();

  const addImage = (pairKey: string, image: ArchiveImageEntry) => {
    const current = byPair.get(pairKey) ?? new Map<string, ArchiveImageEntry>();
    current.set(image.key, image);
    byPair.set(pairKey, current);
  };

  Object.entries(payload.filemap ?? {}).forEach(([relativePath, rawEntry]) => {
    if (!rawEntry || typeof rawEntry !== "object") {
      return;
    }

    const rawMetadata =
      rawEntry.metadata && typeof rawEntry.metadata === "object"
        ? rawEntry.metadata
        : {};
    const metadata: Record<string, string> = {};
    Object.entries(rawMetadata as Record<string, unknown>).forEach(
      ([key, value]) => {
        if (typeof value === "string") {
          metadata[key] = value;
        }
      },
    );

    const zone1 = asZoneKey(metadata.zone_1);
    const zone2 = asZoneKey(metadata.zone_2);
    if (!zone1 || !zone2) {
      return;
    }

    const objectKey =
      typeof rawEntry.key === "string" && rawEntry.key.length > 0
        ? rawEntry.key
        : relativePath;
    const normalizedKey = objectKey.replace(/^\/+/, "");
    if (normalizedKey.length === 0) {
      return;
    }

    const image: ArchiveImageEntry = {
      key: normalizedKey,
      imageUrl: `https://${archiveDomain}/${normalizedKey}`,
      teamName: readTeamName(metadata),
    };

    addImage(makePairKey(zone1, zone2), image);
    addImage(makePairKey(zone2, zone1), image);
  });

  const flattened = new Map<string, ArchiveImageEntry[]>();
  byPair.forEach((images, pairKey) => {
    flattened.set(pairKey, Array.from(images.values()));
  });
  return flattened;
};

const mergeWordReveal = (
  assignments: PublicKingdomRunaroundAssignment[],
  update: WordRevealUpdate,
): PublicKingdomRunaroundAssignment[] => {
  return assignments.map((assignment) => {
    if (assignment.index !== update.assignmentIndex) {
      return assignment;
    }
    return {
      ...assignment,
      words: assignment.words.map((word) => {
        if (word.revealedText) {
          return word;
        }
        const revealedWord = update.revealedWords.find(
          (entry) => entry.wordIndex === word.wordIndex,
        );
        if (!revealedWord) {
          return word;
        }
        return {
          ...word,
          revealedText: revealedWord.text,
        };
      }),
    };
  });
};

const getPromptForAssignment = (
  assignment: PublicKingdomRunaroundAssignment,
): string | null => {
  if (!assignment.zone_1 || !assignment.zone_2) {
    return null;
  }
  const record = PROMPT_RECORDS.find(
    (entry) =>
      (entry.zone_1 === assignment.zone_1 &&
        entry.zone_2 === assignment.zone_2) ||
      (entry.zone_1 === assignment.zone_2 &&
        entry.zone_2 === assignment.zone_1),
  );
  return record?.prompt ?? null;
};

const ArchivalPromptChecker = ({
  assignment,
  shownImages,
  remainingImageCount,
  canAddImage,
  addImageDisabledReason,
  onAddImage,
  onReveal,
}: ArchivalPromptCheckerProps): React.JSX.Element => {
  const [input, setInput] = useState("");
  const [lastCheckTimestamp, setLastCheckTimestamp] = useState(0);
  const [message, setMessage] = useState<string | null>(null);

  const promptMetadata = useMemo(() => {
    const prompt = getPromptForAssignment(assignment);
    return prompt ? buildPromptMetadata(prompt) : null;
  }, [assignment]);

  const isComplete =
    assignment.words.length > 0 &&
    assignment.words.every((word) => Boolean(word.revealedText));

  const handleCheck = useCallback(() => {
    const now = Date.now();
    if (now - lastCheckTimestamp < DEFAULT_RATE_LIMIT_MS) {
      const remaining = Math.ceil(
        (DEFAULT_RATE_LIMIT_MS - (now - lastCheckTimestamp)) / 100,
      );
      setMessage(
        `Rate limited. Try again in ${(remaining / 10).toFixed(1)} seconds.`,
      );
      return;
    }

    setLastCheckTimestamp(now);

    const guess = input;
    const canonicalGuess = canonicalizeWord(guess);
    if (canonicalGuess.length === 0) {
      setMessage("Enter a word to check.");
      return;
    }
    if (!promptMetadata) {
      setMessage("Unable to check this prompt.");
      return;
    }

    const alreadyRevealed = assignment.words.some((word) => {
      if (!word.revealedText) {
        return false;
      }
      return canonicalizeWord(word.revealedText) === canonicalGuess;
    });
    if (alreadyRevealed) {
      setMessage("That word was already confirmed.");
      return;
    }

    const matchingWords = promptMetadata.words.filter(
      (word) => word.canonical === canonicalGuess,
    );
    if (matchingWords.length === 0) {
      setMessage(`"${guess}" does not match this prompt.`);
      return;
    }

    onReveal({
      assignmentIndex: assignment.index,
      revealedWords: matchingWords.map((word) => ({
        wordIndex: word.wordIndex,
        text: word.text,
      })),
    });
    setInput("");
    setMessage(`"${guess}" is now revealed.`);
  }, [assignment, input, lastCheckTimestamp, onReveal, promptMetadata]);

  useEffect(() => {
    if (isComplete) {
      setMessage("Prompt solved.");
    }
  }, [isComplete]);

  return (
    <section
      className={`space-y-4 rounded-lg border p-4 shadow-sm ${
        isComplete
          ? "border-emerald-400 bg-emerald-50"
          : "border-slate-300 bg-slate-50"
      }`}
    >
      <div className="space-y-1">
        <h3 className="text-lg font-semibold text-slate-800">
          Prompt {assignment.index + 1}
        </h3>
      </div>

      <p className="leading-relaxed text-slate-700 font-mono tracking-widest">
        {assignment.tokens.map((token, idx) => {
          if (token.kind === "separator") {
            return <React.Fragment key={idx}>{token.text}</React.Fragment>;
          }
          const word = assignment.words[token.wordIndex];
          const revealed = word?.revealedText;
          const display = revealed ?? "_".repeat(word?.length ?? 1);
          return (
            <span
              key={idx}
              className={`inline-flex flex-col items-center ${
                revealed ? "bg-lime-200 font-semibold text-slate-900" : ""
              }`}
            >
              {display}
              {!revealed ? (
                <span className="text-xs font-normal tracking-normal text-slate-500">
                  ({word?.length ?? 0})
                </span>
              ) : null}
            </span>
          );
        })}
      </p>

      <div className="flex flex-wrap items-end gap-2">
        <label className="flex min-w-48 flex-1 flex-col gap-1">
          <span>Guess a word in the prompt:</span>
          <input
            type="text"
            value={input}
            onChange={(event) => {
              setInput(event.currentTarget.value);
            }}
            onKeyDown={(event) => {
              if (event.key === "Enter") {
                event.preventDefault();
                handleCheck();
              }
            }}
            className="w-full rounded border border-slate-300 px-3 py-2 text-base shadow-sm focus:border-indigo-500 focus:outline-none focus:ring"
            placeholder="Enter a word to guess"
          />
        </label>
        <button
          type="button"
          onClick={handleCheck}
          disabled={shownImages.length === 0 || assignment.words.length === 0}
          className="flex h-10 items-center justify-center rounded bg-indigo-600 px-4 font-medium text-white shadow hover:bg-indigo-500 focus:outline-none focus:ring focus:ring-indigo-200 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Check
        </button>
      </div>
      {shownImages.length === 0 ? (
        <p className="text-xs text-slate-500">
          Add at least one image before checking guesses.
        </p>
      ) : null}
      {message ? <p className="text-sm text-slate-600">{message}</p> : null}

      <div className="space-y-2 rounded border border-slate-200 bg-white p-3">
        <div className="flex flex-wrap items-center gap-2">
          <button
            type="button"
            onClick={onAddImage}
            disabled={!canAddImage}
            className="inline-flex h-9 items-center justify-center rounded bg-slate-900 px-3 text-sm font-semibold text-white shadow hover:bg-slate-800 focus:outline-none focus:ring focus:ring-slate-200 disabled:cursor-not-allowed disabled:opacity-50"
          >
            Show one more image
          </button>
          <span className="text-xs text-slate-600">
            {remainingImageCount > 0
              ? `${remainingImageCount} image${remainingImageCount === 1 ? "" : "s"} remaining`
              : (addImageDisabledReason ?? "All archived images shown.")}
          </span>
        </div>

        {shownImages.length > 0 ? (
          <div className="grid gap-3 md:grid-cols-2">
            {shownImages.map((image, idx) => (
              <figure
                key={`${image.key}-${idx}`}
                className="space-y-1 rounded border border-slate-200 bg-slate-100 p-2"
              >
                <img
                  src={image.imageUrl}
                  alt={`Archived swatch for Prompt ${assignment.index + 1}`}
                  className="max-h-64 w-full rounded object-contain bg-white"
                />
                <figcaption className="text-xs text-slate-600">
                  By {image.teamName}
                </figcaption>
              </figure>
            ))}
          </div>
        ) : null}
      </div>
    </section>
  );
};

export const KingdomRunaroundArchivalMode = ({
  archiveDomain,
}: {
  archiveDomain?: string;
}): React.JSX.Element => {
  const [seedInput, setSeedInput] = useState(DEFAULT_SEED);
  const [activeSeed, setActiveSeed] = useState(DEFAULT_SEED);
  const [assignments, setAssignments] = useState<
    PublicKingdomRunaroundAssignment[]
  >(() => buildAssignmentSetFromSeed(DEFAULT_SEED));
  const [archiveImagesByPair, setArchiveImagesByPair] = useState<
    Map<string, ArchiveImageEntry[]>
  >(new Map());
  const [shownImagesByPrompt, setShownImagesByPrompt] = useState<
    Record<number, ArchiveImageEntry[]>
  >({});
  const [archiveLoadState, setArchiveLoadState] = useState<
    "loading" | "ready" | "error"
  >("loading");
  const [archiveLoadMessage, setArchiveLoadMessage] = useState<string | null>(
    null,
  );
  const [completionState, setCompletionState] = useState<"idle" | "success">(
    "idle",
  );

  const normalizedArchiveDomain = useMemo(() => {
    return normalizeArchiveDomain(
      archiveDomain ?? getArchiveDomainFromWindow(),
    );
  }, [archiveDomain]);

  useEffect(() => {
    setAssignments(mergeStoredRevealed(buildAssignmentSetFromSeed(activeSeed)));
    setShownImagesByPrompt({});
    setCompletionState("idle");
  }, [activeSeed]);

  useEffect(() => {
    const domain = normalizedArchiveDomain;
    if (!domain) {
      setArchiveImagesByPair(new Map());
      setArchiveLoadState("error");
      setArchiveLoadMessage("MIDHUNT_ARCHIVE_DOMAIN is not configured.");
      return;
    }

    const controller = new AbortController();
    setArchiveLoadState("loading");
    setArchiveLoadMessage(null);

    void (async () => {
      const indexUrl = `https://${domain}/by-prompt/index.json`;
      try {
        const response = await fetch(indexUrl, {
          credentials: "omit",
          signal: controller.signal,
        });
        if (!response.ok) {
          throw new Error(`status ${response.status}`);
        }
        const payload = (await response.json()) as ArchiveIndexPayload;
        if (controller.signal.aborted) {
          return;
        }
        setArchiveImagesByPair(
          buildArchiveImageIndex({
            payload,
            archiveDomain: domain,
          }),
        );
        setArchiveLoadState("ready");
      } catch (error: unknown) {
        if (controller.signal.aborted) {
          return;
        }
        console.warn("Failed to load archival Kingdom Runaround index", error);
        setArchiveImagesByPair(new Map());
        setArchiveLoadState("error");
        setArchiveLoadMessage(
          `Unable to load archived images from https://${domain}/by-prompt/index.json.`,
        );
      }
    })();

    return () => {
      controller.abort();
    };
  }, [normalizedArchiveDomain]);

  const onReveal = useCallback((update: WordRevealUpdate) => {
    setAssignments((previous) => {
      const next = mergeWordReveal(previous, update);
      const assignment = next[update.assignmentIndex];
      if (assignment?.zone_1 && assignment?.zone_2) {
        const pairKey = makePairKey(assignment.zone_1, assignment.zone_2);
        const revealed = assignment.words
          .filter((w): w is typeof w & { revealedText: string } =>
            Boolean(w.revealedText),
          )
          .map((w) => ({ wordIndex: w.wordIndex, text: w.revealedText }));
        saveStoredRevealedForPair(pairKey, revealed);
      }
      return next;
    });
  }, []);

  const addRandomImage = useCallback(
    (assignment: PublicKingdomRunaroundAssignment) => {
      if (!assignment.zone_1 || !assignment.zone_2) {
        return;
      }

      const pairKey = makePairKey(assignment.zone_1, assignment.zone_2);
      const allImages = archiveImagesByPair.get(pairKey) ?? [];

      setShownImagesByPrompt((previous) => {
        const currentShown = previous[assignment.index] ?? [];
        const currentKeys = new Set(currentShown.map((entry) => entry.key));
        const remaining = allImages.filter(
          (entry) => !currentKeys.has(entry.key),
        );
        if (remaining.length === 0) {
          return previous;
        }

        const selected =
          remaining[Math.floor(Math.random() * remaining.length)];
        if (!selected) {
          return previous;
        }
        return {
          ...previous,
          [assignment.index]: currentShown.concat(selected),
        };
      });
    },
    [archiveImagesByPair],
  );

  const solvedPromptCount = useMemo(
    () =>
      assignments.filter(
        (assignment) =>
          assignment.words.length > 0 &&
          assignment.words.every((word) => Boolean(word.revealedText)),
      ).length,
    [assignments],
  );

  const allSolved =
    assignments.length > 0 && solvedPromptCount === assignments.length;

  const markArchivalCompleted = useCallback(() => {
    // In original hunt, this was a puzzle, but for archival, it is easiest to treat as task
    markLocalTaskSolved(KINGDOM_RUNAROUND_SLUG, "✅");
    setCompletionState("success");
  }, []);

  useEffect(() => {
    if (!allSolved || completionState !== "idle") {
      return;
    }
    markArchivalCompleted();
  }, [allSolved, completionState, markArchivalCompleted]);

  return (
    <div className="space-y-6">
      <div className="rounded-lg border border-slate-200 bg-white/60 p-4 text-sm text-slate-700 shadow-sm space-y-3">
        <p>Enter a seed to choose a set of 9 prompts.</p>

        <form
          className="flex flex-wrap items-end gap-2"
          onSubmit={(event) => {
            event.preventDefault();
            const nextSeed =
              seedInput.trim().length > 0 ? seedInput.trim() : DEFAULT_SEED;
            setSeedInput(nextSeed);
            setActiveSeed(nextSeed);
          }}
        >
          <label className="flex min-w-56 flex-1 flex-col gap-1">
            <span className="text-xs uppercase tracking-wide text-slate-500">
              Seed
            </span>
            <input
              type="text"
              value={seedInput}
              onChange={(event) => {
                setSeedInput(event.currentTarget.value);
              }}
              className="w-full rounded border border-slate-300 px-3 py-2 text-base shadow-sm focus:border-indigo-500 focus:outline-none focus:ring"
              placeholder="Enter a seed"
            />
          </label>
          <button
            type="submit"
            className="inline-flex h-10 items-center justify-center rounded bg-indigo-600 px-4 font-medium text-white shadow hover:bg-indigo-500 focus:outline-none focus:ring focus:ring-indigo-200"
          >
            Apply seed
          </button>
        </form>

        <div className="space-y-1 text-xs text-slate-600">
          <p>Active seed: {activeSeed}</p>
          <p>
            Solved prompts: {solvedPromptCount}/{assignments.length}
          </p>
          {archiveLoadState === "loading" ? (
            <p>Loading archived image index...</p>
          ) : archiveLoadState === "error" ? (
            <p>{archiveLoadMessage}</p>
          ) : null}
        </div>
      </div>

      <div className="grid gap-6">
        {assignments.map((assignment) => {
          const shownImages = shownImagesByPrompt[assignment.index] ?? [];
          const pairKey =
            assignment.zone_1 && assignment.zone_2
              ? makePairKey(assignment.zone_1, assignment.zone_2)
              : null;
          const allImages = pairKey
            ? (archiveImagesByPair.get(pairKey) ?? [])
            : ([] as ArchiveImageEntry[]);
          const remainingImageCount = Math.max(
            0,
            allImages.length - shownImages.length,
          );

          const canAddImage =
            archiveLoadState === "ready" && remainingImageCount > 0;
          const addImageDisabledReason =
            archiveLoadState === "loading"
              ? "Loading image index..."
              : archiveLoadState === "error"
                ? "Archived image index unavailable."
                : allImages.length === 0
                  ? "No archived images available for this prompt."
                  : "All archived images shown.";

          return (
            <ArchivalPromptChecker
              key={`${activeSeed}-${assignment.index}`}
              assignment={assignment}
              shownImages={shownImages}
              remainingImageCount={remainingImageCount}
              canAddImage={canAddImage}
              addImageDisabledReason={addImageDisabledReason}
              onAddImage={() => {
                addRandomImage(assignment);
              }}
              onReveal={onReveal}
            />
          );
        })}
      </div>
    </div>
  );
};
