import { PROMPT_RECORDS, VALID_ZONE_CHAINS } from "./data";
import { type ZoneKey, ZONES } from "./zones";
export { type ZoneKey, ZONES, ZONE_DISPLAY_NAMES } from "./zones";

export type PromptAssignment = {
  index: number;
  zone_1: ZoneKey;
  zone_2: ZoneKey;
  prompt: string;
};

export const makePairKey = (zone_1: ZoneKey, zone_2: ZoneKey): string =>
  `${zone_1}|${zone_2}`;

const PROMPT_INDEX_BY_PAIR = (() => {
  const map = new Map<string, number>();
  PROMPT_RECORDS.forEach((record, index) => {
    const forward = makePairKey(record.zone_1, record.zone_2);
    const reverse = makePairKey(record.zone_2, record.zone_1);
    map.set(forward, index);
    map.set(reverse, index);
  });
  return map;
})();

const hashTeamId = (teamId: number): number => {
  let value = teamId | 0;
  value ^= value >>> 17;
  value = Math.imul(value, 0xed5ad4bb);
  value ^= value >>> 11;
  value = Math.imul(value, 0xac4c1b51);
  value ^= value >>> 15;
  value = Math.imul(value, 0x31848bab);
  value ^= value >>> 14;
  return value >>> 0;
};

const hashSeedString = (seed: string): number => {
  let hash = 0x811c9dc5;
  for (const char of seed) {
    hash ^= char.charCodeAt(0);
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
};

const parseSeedToTeamLikeId = (seed: string): number => {
  const trimmed = seed.trim();
  if (trimmed.length === 0) {
    return 0;
  }
  if (/^-?\d+$/.test(trimmed)) {
    const parsed = Number.parseInt(trimmed, 10);
    if (!Number.isNaN(parsed)) {
      return parsed;
    }
  }
  return hashSeedString(trimmed);
};

const selectAssignments = (seedValue: number): PromptAssignment[] => {
  if (PROMPT_RECORDS.length === 0 || VALID_ZONE_CHAINS.length === 0) {
    return [];
  }

  const chain =
    VALID_ZONE_CHAINS[hashTeamId(seedValue) % VALID_ZONE_CHAINS.length] ??
    ZONES;

  const assignments: PromptAssignment[] = [];
  const appendAssignment = (recordIndex: number) => {
    const record = PROMPT_RECORDS[recordIndex];
    assignments.push({
      index: assignments.length,
      zone_1: record.zone_1,
      zone_2: record.zone_2,
      prompt: record.prompt,
    });
  };

  for (let i = 0; i < chain.length; i += 1) {
    const from = chain[i];
    const to = chain[(i + 1) % chain.length];
    const recordIndex = PROMPT_INDEX_BY_PAIR.get(makePairKey(from, to));
    if (recordIndex !== undefined) {
      appendAssignment(recordIndex);
    }
  }

  return assignments.slice(0, chain.length);
};

export const getAssignmentForTeam = (teamId: number): PromptAssignment[] => {
  return selectAssignments(teamId);
};

export const getAssignmentForSeed = (seed: string): PromptAssignment[] => {
  return selectAssignments(parseSeedToTeamLikeId(seed));
};
