import React, { createContext, useContext } from "react";
import { type PublicKingdomRunaroundAssignment } from "./publicTypes";

type ProviderProps = {
  assignments?: PublicKingdomRunaroundAssignment[];
  children: React.ReactNode;
};

const KingdomRunaroundAssignmentsContext = createContext<
  PublicKingdomRunaroundAssignment[] | undefined
>(undefined);

export const KingdomRunaroundAssignmentsProvider = ({
  assignments,
  children,
}: ProviderProps): React.JSX.Element => {
  return (
    <KingdomRunaroundAssignmentsContext.Provider value={assignments}>
      {children}
    </KingdomRunaroundAssignmentsContext.Provider>
  );
};

export const useKingdomRunaroundAssignmentsContext = () => {
  return useContext(KingdomRunaroundAssignmentsContext);
};
