const BANNED_SLUG_PAIRS: readonly [ZoneSlug, ZoneSlug][] = [
  [AVIARIA, ELAND_ISLANDS],
  [ELAND_ISLANDS, THE_BRIGHTS],
  [THE_BRIGHTS, ROYAL_GROVES],
  [ROYAL_GROVES, ELDER_DRIFTS],
  [ELDER_DRIFTS, BUBBLE_COVE],
  [BUBBLE_COVE, OLD_BARK_TOWN],
  [OLD_BARK_TOWN, KITTY_CITY],
  [KITTY_CITY, SERPENTINE_HILLS],
  [SERPENTINE_HILLS, AVIARIA],
];

const BANNED_ZONE_PAIRS = new Set<string>(
  BANNED_SLUG_PAIRS.flatMap(([from, to]) => [`${from}|${to}`, `${to}|${from}`]),
);

const PAIRS_WITH_PROMPTS = new Set<string>(
  PROMPT_RECORDS.flatMap(({ zone_1, zone_2 }) => [
    `${zone_1}|${zone_2}`,
    `${zone_2}|${zone_1}`,
  ]),
);

const equivalentChains = (order: readonly number[]): string[] => {
  const rotationList: string[] = [];
  const n = order.length;
  for (let offset = 0; offset < n; offset += 1) {
    const rotated: number[] = [];
    for (let i = 0; i < n; i += 1) {
      rotated.push(order[(offset + i) % n]);
    }
    rotationList.push(rotated.join(","));
  }
  const reversed = [...order].reverse();
  for (let offset = 0; offset < n; offset += 1) {
    const rotated: number[] = [];
    for (let i = 0; i < n; i += 1) {
      rotated.push(reversed[(offset + i) % n]);
    }
    rotationList.push(rotated.join(","));
  }
  return rotationList;
};

const canonicalBracelet = (order: readonly number[]): string =>
  equivalentChains(order).reduce((minValue, candidate) =>
    candidate < minValue ? candidate : minValue,
  );

const generateUniqueOrders = (): number[][] => {
  const n = OVERWORLD_ROUND_SLUGS.length;
  const seen = new Set<string>();
  const current: number[] = new Array<number>(n);
  const used = new Array<boolean>(n).fill(false);
  const results: number[][] = [];

  const backtrack = (position: number) => {
    if (position === n) {
      const canonical = canonicalBracelet(current);
      if (!seen.has(canonical)) {
        seen.add(canonical);
        results.push([...current]);
      }
      return;
    }
    for (let i = 0; i < n; i += 1) {
      if (used[i]) {
        continue;
      }
      used[i] = true;
      current[position] = i;
      backtrack(position + 1);
      used[i] = false;
    }
  };

  backtrack(0);
  return results;
};

const isChainValid = (order: readonly number[]): boolean => {
  const n = order.length;
  for (let i = 0; i < n; i += 1) {
    const from = OVERWORLD_ROUND_SLUGS[order[i]];
    const to = OVERWORLD_ROUND_SLUGS[order[(i + 1) % n]];
    if (BANNED_ZONE_PAIRS.has(`${from}|${to}`)) {
      return false;
    }
    if (!PAIRS_WITH_PROMPTS.has(`${from}|${to}`)) {
      return false;
    }
  }
  return true;
};

const generateValidChains = (): readonly (readonly ZoneSlug[])[] => {
  const uniqueOrders = generateUniqueOrders();
  const filtered = uniqueOrders
    .filter(isChainValid)
    .map(
      (order) =>
        order.map(
          (index) => OVERWORLD_ROUND_SLUGS[index],
        ) as readonly ZoneSlug[],
    );
  return dontLeakThis(filtered as readonly (readonly ZoneSlug[])[]);
};

export const VALID_ZONE_CHAINS = generateValidChains();
